import{_ as i,l,o as e,c as o,v as r,p as n,x as s,d as E,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"太阳黑子均衡","description":"","frontmatter":{"title":"太阳黑子均衡","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/sunspot-equilibrium.md","filePath":"econ/sunspot-equilibrium.md","lastUpdated":1789023840000}'),h={name:"econ/sunspot-equilibrium.md"};function c(A,a,u,m,B,_){const t=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="太阳黑子均衡" tabindex="-1">太阳黑子均衡 <a class="header-anchor" href="#太阳黑子均衡" aria-label="Permalink to &quot;太阳黑子均衡&quot;">​</a></h1><div class="epigraph"><p>与基本面无关的外在不确定性，只要被共同相信，就可以进入均衡价格与配置。</p><footer>—— Cass and Shell, Do Sunspots Matter?, Journal of Political Economy, 1983</footer></div><p><a href="/econ/radner-plans">上一课</a>（Radner 均衡）。把证券张成写成真子空间：Radner 均衡只在可交易方向上对齐状态间 MRS，缺的方向无法保险，配置一般不是完全市场帕累托。缺口是这些缺掉的维度，会不会被「不影响禀赋、偏好与技术的随机信号」填上。本课钉太阳黑子：外在不确定性可以自我实现。不重写 GEI 的张成代数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>外在不确定性（extrinsic）是不改基本面的随机变量：哪个太阳黑子实现，都不改变 \\(\\omega\\)、\\(u\\)、生产集或证券红利。内在不确定性（intrinsic）则直接改这些对象。<a href="/econ/state-contingent">状态依存</a>课里的下雨、违约是内在的。Cass–Shell 问的是前者：若人人把黑子写进预期，现货价格能否随黑子变，从而使配置也随黑子变？</p><p>完全市场、凸偏好、全员可买 Arrow 证券时，答案是否定的（太阳黑子无关）：黑子状态也可以被保险，凸性让「同基本面、不同消费」的随机化不优于确定性，均衡配置不依赖外在信号。GEI 或受限参与拆掉这张保险网，黑子可以进均衡。</p><h3 id="黑子不是农业减产" tabindex="-1">黑子不是农业减产 <a class="header-anchor" href="#黑子不是农业减产" aria-label="Permalink to &quot;黑子不是农业减产&quot;">​</a></h3><p>太阳活动伤作物，那是内在冲击，不是本课对象。本课的黑子可以是任何公共随机装置：日斑、权威预言、与支付无关的阳光。它起作用是因为信念协调，不是因为物理进入生产函数。</p><p><span class="marginnote">Cass–Shell 的参与限制：一部分人被挡在证券门外，只能做现货。即使证券看起来不少，被挡的人无法对冲黑子，现货价格仍可随黑子跳。不完全张成是同一缺口的资产版本。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两期、有限外在状态 \\(s\\)，基本面在 \\(s\\) 上相同。证券在期初交易，现货在 \\(s\\) 实现后开。GEI：证券种类少于对冲黑子所需。寻找 Radner 均衡，使不同 \\(s\\) 的现货价格 \\(p(s)\\) 不同，从而 \\(x(s)\\) 不同。这就是太阳黑子均衡。</p><p>对照：把每个 \\(s\\) 当成普通内在状态、补齐 Arrow 证券，回到完全市场，黑子熄灭。本课不把黑子均衡当成太阳物理学，也不写成限价簿上的公共信号。</p>',12)),(e(),n(d,null,{default:s(()=>[p(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEI%5B%22GEI%EF%BC%9A%E5%BC%A0%E6%88%90%E4%B8%8D%E8%B6%B3%22%5D%20--%3E%20EXT%5B%22%E5%A4%96%E5%9C%A8%E4%BF%A1%E5%8F%B7%20s%EF%BC%8C%E5%9F%BA%E6%9C%AC%E9%9D%A2%E4%B8%8D%E5%8F%98%22%5D%0A%20%20EXT%20--%3E%20BEL%5B%22%E5%85%B1%E5%90%8C%E4%BF%A1%E5%BF%B5%EF%BC%9Ap%20%E9%9A%8F%20s%20%E5%8F%98%22%5D%0A%20%20BEL%20--%3E%20SSE%5B%22%E5%A4%AA%E9%98%B3%E9%BB%91%E5%AD%90%E5%9D%87%E8%A1%A1%EF%BC%9A%E9%85%8D%E7%BD%AE%E9%9A%8F%20s%20%E5%8F%98%22%5D%0A%20%20COMP%5B%22%E5%AE%8C%E5%85%A8%E5%B8%82%E5%9C%BA%E5%8A%A0%E5%87%B8%E6%80%A7%22%5D%20--%3E%20NO%5B%22%E9%BB%91%E5%AD%90%E6%97%A0%E5%85%B3%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>信念是协调装置。若大家都预期 \\(s=\\) 斑时价格低，资产需求与期二超额需求按这个预期写，出清价格可以真的低。完全市场上可以买「斑时赔付」的证券，把价格风险对冲掉；凸偏好下确定性更好，支持「\\(p\\) 随 \\(s\\) 变」的预期站不住。GEI 缺这张证券，预期不必被保险市场拆穿。</p><p>受限参与同样：被挡在证券门外的人只能靠现货消化黑子，他们的需求把 \\(p(s)\\) 拉开，能交易的人无法单独熄灭黑子。Cass–Shell 定理的「无关」方向要全员都能买卖一套对黑子状态也完备的 Arrow 证券；缺一边参与，无关性立刻掉。</p><h3 id="外在信号可以部分补市场-也可以纯浪费" tabindex="-1">外在信号可以部分补市场，也可以纯浪费 <a class="header-anchor" href="#外在信号可以部分补市场-也可以纯浪费" aria-label="Permalink to &quot;外在信号可以部分补市场，也可以纯浪费&quot;">​</a></h3><p>有时黑子碰巧提供额外随机化，让原本不可张成的方向变得可交易，福利可以升。有时只是在本已可保险的方向上加噪声，福利降。GEI 已经约束无效，符号不先验。本课要的是「可以自我实现」，不是「黑子一定有害」或「一定完成市场」。</p><p><span class="marginnote">Azariadis 在叠代货币模型里用太阳黑子做内生波动：基本面确定，信念仍可在高价与低价轨道间跳。那是宏观应用；本课的定义仍是 Cass–Shell 的外在不确定性进均衡。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不是任何随机预言都是均衡：\\(p(s)\\) 仍须出清，预算仍须守。连续统黑子、非凸、名义资产的不定性（价格水平随外在信号跳）是同一思想的技术延伸，主干不展开。也不要把太阳黑子写成量化栏的公共信息到达；这里没有队列。</p><p>与<a href="/econ/correlated-equilibrium">相关均衡</a>的对照留到博弈课：那里外在信号协调行动，这里协调价格。两边都要求信号不改基本面；市场结构决定信号能不能被保险掉。</p><p>配置课序到此：商品空间、张成、外在信念能做什么，已经齐。后课问根本没被列进商品空间的影响——那是外部性，不是再加一张证券。</p><p>后课默认：谈到外在不确定性，先问市场是否完全、参与是否受限；完全且凸则黑子无关，GEI 里可以有太阳黑子均衡。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>外在不确定性不改基本面；完全市场加凸性时它不进入配置。</li><li>GEI 或受限参与下，共同信念可让价格与配置随黑子变。</li><li>机制是自我实现的预期，不是物理进入生产函数。</li><li>黑子可改善也可恶化约束有效性，符号不免费。</li><li>出处：Cass and Shell, <em>JPE</em>, 1983；Shell, 1977；Azariadis, <em>JET</em>, 1981。</li></ul>',13))])}const b=i(h,[["render",c]]);export{C as __pageData,b as default};
